<template><main v-if="ticket" class="store-shell py-5"><section class="store-card p-4"><div class="d-flex justify-content-between"><div><small>{{ticket.ticket_number}}</small><h1 class="h3">{{ticket.subject}}</h1></div><button class="store-btn" @click="toggle">{{ticket.status==="closed"?"Reopen":"Close"}}</button></div><article v-for="m in ticket.messages" :key="m.id" class="border rounded p-3 my-3" :class="m.is_admin?'bg-light':''"><strong>{{m.user?.name}}</strong><small class="ms-2">{{m.is_admin?"Support":"You"}}</small><p class="mb-0 mt-2">{{m.message}}</p></article><form v-if="ticket.status!=='closed'" class="d-flex gap-2" @submit.prevent="reply"><textarea v-model="message" class="store-input form-control" required></textarea><button class="store-btn store-btn--primary">Reply</button></form></section></main></template>
<script setup>
import {onMounted,ref} from "vue"; import {useRoute} from "vue-router"; import {useSeoMeta} from "@/composables/useSeoMeta"; import service from "@/services/home/TicketService";
const route=useRoute(),ticket=ref(null),message=ref(""); useSeoMeta({title:"Support ticket",robots:"noindex,nofollow"}); const load=async()=>ticket.value=(await service.show(route.params.id)).data; const reply=async()=>{await service.reply(ticket.value.id,message.value);message.value="";await load()}; const toggle=async()=>{await service.status(ticket.value.id,ticket.value.status==="closed"?"open":"closed");await load()}; onMounted(load);
</script>
